setAuditedAnswerAt('estimated-03',1,'مَرَرْتُ','فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى السُّكُونِ، وَالتَّاءُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.','Past verb built on sukūn; tāʾ is its attached subject. Subject tāʾ is an attached pronoun built on ḍamm.');
setAuditedPartsAt('estimated-03',2,'بِغُلَامِي',[{ar:'الْبَاءُ حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْكَسْرِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.',en:'Bāʾ is a preposition. Bāʾ is built on kasr and has no syntactic position.'},{ar:'«غُلَامِ» اسْمٌ مَجْرُورٌ بِالْبَاءِ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الْمُقَدَّرَةُ عَلَى مَا قَبْلَ يَاءِ الْمُتَكَلِّمِ، مَنَعَ مِنْ ظُهُورِهَا اشْتِغَالُ الْمَحَلِّ بِحَرَكَةِ الْمُنَاسَبَةِ، وَهُوَ مُضَافٌ.',en:'Ghulām is governed by bāʾ, genitive with an estimated kasrah before the speaker’s yāʾ; the place is occupied by the matching kasrah. It begins an iḍāfah.'},{ar:'يَاءُ الْمُتَكَلِّمِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.',en:'The speaker’s yāʾ is an attached pronoun in the genitive position as the second term. The speaker’s yāʾ is built on sukūn.'}]);
setAuditedPartsAt('estimated-03',3,'وَابْنِي',[{ar:'الْوَاوُ حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.',en:'Wāw is a conjunction. Wāw is built on fatḥ and has no syntactic position.'},{ar:'«ابْنِ» مَعْطُوفٌ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الْمُقَدَّرَةُ عَلَى مَا قَبْلَ يَاءِ الْمُتَكَلِّمِ، مَنَعَ مِنْ ظُهُورِهَا اشْتِغَالُ الْمَحَلِّ بِحَرَكَةِ الْمُنَاسَبَةِ، وَهُوَ مُضَافٌ.',en:'Ibn is coordinated and genitive with an estimated kasrah before the speaker’s yāʾ; the place is occupied by the matching kasrah. It begins an iḍāfah.'},{ar:'يَاءُ الْمُتَكَلِّمِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.',en:'The speaker’s yāʾ is an attached pronoun in the genitive position as the second term. The speaker’s yāʾ is built on sukūn.'}]);
setAuditedAnswerAt('estimated-05',1,'رَأَيْتُ','فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى السُّكُونِ، وَالتَّاءُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.','Past verb built on sukūn; tāʾ is its attached subject. Subject tāʾ is an attached pronoun built on ḍamm.');
setAuditedAnswerAt('estimated-06',1,'مَرَرْتُ','فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى السُّكُونِ، وَالتَّاءُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.','Past verb built on sukūn; tāʾ is its attached subject. Subject tāʾ is an attached pronoun built on ḍamm.');
setAuditedPartsAt('estimated-06',2,'بِالْفَتَى',[{ar:'الْبَاءُ حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْكَسْرِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.',en:'Bāʾ is a preposition. Bāʾ is built on kasr and has no syntactic position.'},{ar:'«الْفَتَى» اسْمٌ مَجْرُورٌ بِالْبَاءِ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الْمُقَدَّرَةُ عَلَى الْأَلِفِ لِلتَّعَذُّرِ.',en:'Al-fatā is governed by bāʾ, genitive with an estimated kasrah on the alif because the vowel cannot appear there.'}]);
setAuditedPartsAt('estimated-09',1,'أَجِيبُوا',[{ar:'«أَجِيبُوا» فِعْلُ أَمْرٍ مَبْنِيٌّ عَلَى حَذْفِ النُّونِ.',en:'Ajībū is an imperative built on deletion of nūn.'},{ar:'وَاوُ الْجَمَاعَةِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ فَاعِلٌ، وَالْأَلِفُ فَارِقَةٌ.',en:'Plural wāw is its attached subject; the final alif is orthographic. Plural wāw is an attached pronoun built on sukūn.'}]);
setAuditedPartsAt('diptote-03',1,'إِنَّا',[{ar:'«إِنَّ» حَرْفُ تَوْكِيدٍ وَنَصْبٍ مَبْنِيٌّ عَلَى الْفَتْحِ.',en:'Inna is a particle of emphasis and naṣb, built on fatḥ.'},{ar:'«نَا» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ اسْمُ «إِنَّ».',en:'Nā is an attached pronoun in the accusative position as the subject of inna. Nā is an attached pronoun built on sukūn.'}]);
setAuditedPartsAt('diptote-03',2,'أَعْتَدْنَا',[{ar:'«أَعْتَدْ» فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى السُّكُونِ لِاتِّصَالِهِ بِـ«نَا» الْفَاعِلِينَ.',en:'Aʿtad is a past verb built on sukūn because subject nā is attached.'},{ar:'«نَا» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ فَاعِلٌ، وَالْجُمْلَةُ فِي مَحَلِّ رَفْعٍ خَبَرُ «إِنَّ».',en:'Nā is its attached subject; the clause is in the nominative position as the predicate of inna. Nā is an attached pronoun built on sukūn.'}]);
setAuditedPartsAt('diptote-03',3,'لِلْكَافِرِينَ',[{ar:'اللَّامُ حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْكَسْرِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.',en:'Lām is a preposition. Lām is built on kasr and has no syntactic position.'},{ar:'«الْكَافِرِينَ» اسْمٌ مَجْرُورٌ بِاللَّامِ، وَعَلَامَةُ جَرِّهِ الْيَاءُ نِيَابَةً عَنِ الْكَسْرَةِ؛ لِأَنَّهُ جَمْعُ مُذَكَّرٍ سَالِمٌ.',en:'Al-kāfirīna is governed by lām, genitive with yāʾ instead of kasrah because it is a sound masculine plural.'}]);
setAuditedPartsAt('diptote-03',5,'وَأَغْلَالًا',[{ar:'الْوَاوُ حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.',en:'Wāw is a conjunction. Wāw is built on fatḥ and has no syntactic position.'},{ar:'«أَغْلَالًا» مَعْطُوفٌ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.',en:'Aghlālan is coordinated and accusative with a visible fatḥah.'}]);
setAuditedPartsAt('diptote-03',6,'وَسَعِيرًا',[{ar:'الْوَاوُ حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.',en:'Wāw is a conjunction. Wāw is built on fatḥ and has no syntactic position.'},{ar:'«سَعِيرًا» مَعْطُوفٌ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.',en:'Saʿīran is coordinated and accusative with a visible fatḥah.'}]);

// Five clauses already said “built” but omitted the actual fixed ending.
setAuditedAnswerAt('raf-14',4,'إِلَى','حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى السُّكُونِ الْمُقَدَّرِ عَلَى الْأَلِفِ لِلتَّعَذُّرِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.','A preposition built on an estimated sukūn on its final alif, with no syntactic position.');
setAuditedAnswerAt('nasb-08',1,'مَا','حَرْفُ نَفْيٍ مَبْنِيٌّ عَلَى السُّكُونِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.','A negating particle built on sukūn, with no syntactic position.');
setAuditedAnswerAt('nasb-11',1,'أَنْ','حَرْفٌ مَصْدَرِيٌّ مَبْنِيٌّ عَلَى السُّكُونِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.','A source-forming particle built on sukūn, with no syntactic position.');
setAuditedAnswerAt('nasb-19',2,'أَنْ','حَرْفُ مَصْدَرٍ وَنَصْبٍ وَاسْتِقْبَالٍ مَبْنِيٌّ عَلَى السُّكُونِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.','A source-forming, subjunctive, and future particle built on sukūn, with no syntactic position.');
setAuditedAnswerAt('nasb-20',1,'وَأَنْ','الْوَاوُ حَرْفُ اسْتِئْنَافٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«أَنْ» حَرْفُ مَصْدَرٍ وَنَصْبٍ وَاسْتِقْبَالٍ مَبْنِيٌّ عَلَى السُّكُونِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.','The resumption wāw is built on fatḥ and has no syntactic position. An is a source-forming, subjunctive, and future particle built on sukūn, with no syntactic position.');

// Context-specific fixed-ending details found by the final pages 19–71 parity pass.
setAuditedAnswerAt('raf-14',1,'لَيُوسُفُ','اللَّامُ حَرْفُ ابْتِدَاءٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«يُوسُفُ» مُبْتَدَأٌ مَرْفُوعٌ بِالضَّمَّةِ الظَّاهِرَةِ.','The initial lām is built on fatḥ and has no syntactic position. Yūsufu is the mubtadaʾ, nominative with a visible ḍammah.');
setAuditedAnswerAt('verb-17',1,'لَيُسْجَنَنَّ','اللَّامُ حَرْفُ جَوَابِ قَسَمٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«يُسْجَنَنَّ» فِعْلٌ مُضَارِعٌ مَبْنِيٌّ لِلْمَجْهُولِ مَبْنِيٌّ عَلَى الْفَتْحِ لِاتِّصَالِهِ بِنُونِ التَّوْكِيدِ الثَّقِيلَةِ، وَنُونُ التَّوْكِيدِ حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَنَائِبُ فَاعِلِهِ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.','The oath-response lām is built on fatḥ and has no syntactic position. Yusjananna is a passive present verb built on fatḥ because heavy emphasis nūn is attached; that nūn is built on fatḥ and has no syntactic position. Its hidden deputy subject is “he.”');
setAuditedAnswerAt('verb-17',2,'وَلَيَكُونًا','الْوَاوُ حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَاللَّامُ حَرْفُ جَوَابِ قَسَمٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«يَكُونًا» فِعْلٌ مُضَارِعٌ نَاقِصٌ مَبْنِيٌّ عَلَى الْفَتْحِ لِاتِّصَالِهِ بِنُونِ التَّوْكِيدِ الْخَفِيفَةِ، وَنُونُ التَّوْكِيدِ الْخَفِيفَةُ حَرْفٌ مَبْنِيٌّ عَلَى السُّكُونِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَاسْمُهُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ.','The coordinating wāw and oath-response lām are each built on fatḥ and have no syntactic position. Yakūnan is a deficient present verb built on fatḥ because light emphasis nūn is attached; that nūn is built on sukūn and has no syntactic position. Its hidden subject is “he.”');
setAuditedAnswerAt('raf-16',1,'وَهَذَا','الْوَاوُ حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَهَاءُ التَّنْبِيهِ حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«ذَا» اسْمُ إِشَارَةٍ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ.','The coordinating wāw and attention hāʾ are each built on fatḥ and have no syntactic position. Dhā is a demonstrative built on sukūn in the nominative position as mubtadaʾ.');
setAuditedAnswerAt('raf-17',1,'وَإِنَّهُ','الْوَاوُ حَرْفُ حَالٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«إِنَّ» حَرْفُ تَوْكِيدٍ وَنَصْبٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَالْهَاءُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ نَصْبٍ اسْمُ «إِنَّ».','The circumstantial wāw is built on fatḥ and has no syntactic position. Inna is a particle of emphasis and naṣb built on fatḥ with no syntactic position; hāʾ is an attached pronoun built on ḍamm in the accusative position as its noun.');
setAuditedAnswerAt('raf-17',2,'لَذُو','اللَّامُ حَرْفُ تَوْكِيدٍ مُزَحْلَقٌ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«ذُو» خَبَرُ «إِنَّ» مَرْفُوعٌ بِالْوَاوِ نِيَابَةً عَنِ الضَّمَّةِ؛ لِأَنَّهُ مِنَ الْأَسْمَاءِ السِّتَّةِ وَهُوَ مُضَافٌ.','The displaced lām of emphasis is built on fatḥ and has no syntactic position. Dhū is the predicate of inna, nominative with wāw instead of ḍammah because it is one of the six nouns and is annexed.');
setAuditedAnswerAt('khafd-13',1,'فَإِطْعَامُ','الْفَاءُ رَابِطَةٌ لِجَوَابِ الشَّرْطِ الْمُتَقَدِّمِ، وَهِيَ حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«إِطْعَامُ» مُبْتَدَأٌ مَرْفُوعٌ بِالضَّمَّةِ الظَّاهِرَةِ وَهُوَ مُضَافٌ، وَخَبَرُهُ مَحْذُوفٌ.','The fāʾ links the earlier condition to its answer; it is built on fatḥ and has no syntactic position. Iṭʿāmu is a mubtadaʾ nominative with a visible ḍammah and the first term of an iḍāfah; its predicate is omitted.');
setAuditedAnswerAt('khafd-15',1,'فَحَيُّوا','الْفَاءُ رَابِطَةٌ لِجَوَابِ «إِذَا» فِي سِيَاقِ الْآيَةِ، وَهِيَ حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«حَيُّوا» فِعْلُ أَمْرٍ مَبْنِيٌّ عَلَى حَذْفِ النُّونِ، وَوَاوُ الْجَمَاعَةِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.','The fāʾ links the answer to idhā in the verse’s context; it is built on fatḥ and has no syntactic position. Ḥayyū is an imperative built on deletion of nūn; plural wāw is an attached pronoun built on sukūn in the nominative position as subject.');
setAuditedAnswerAt('khafd-18',1,'وَأَنْتُمْ','الْوَاوُ حَرْفُ حَالٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«أَنْتُمْ» ضَمِيرٌ مُنْفَصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ؛ «أَنْ» أَصْلُ الضَّمِيرِ، وَالتَّاءُ حَرْفُ خِطَابٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَالْمِيمُ عَلَامَةُ الْجَمْعِ.','The circumstantial wāw is built on fatḥ and has no syntactic position. Antum is a detached pronoun built on sukūn in the nominative position as mubtadaʾ; an is the pronominal base, the address tāʾ is built on fatḥ with no syntactic position, and mīm marks the plural.');
setAuditedAnswerAt('summary-01',1,'جَاءَنِي','«جَاءَ» فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى الْفَتْحِ، وَنُونُ الْوِقَايَةِ حَرْفٌ مَبْنِيٌّ عَلَى الْكَسْرِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَالْيَاءُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ.','Jāʾa is a past verb built on fatḥ. Protective nūn is built on kasr and has no syntactic position; yāʾ is an attached pronoun built on sukūn in the accusative position as its object.');
setAuditedAnswerAt('summary-04',1,'جَاءَنِي','«جَاءَ» فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى الْفَتْحِ، وَنُونُ الْوِقَايَةِ حَرْفٌ مَبْنِيٌّ عَلَى الْكَسْرِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَالْيَاءُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ.','Jāʾa is a past verb built on fatḥ. Protective nūn is built on kasr and has no syntactic position; yāʾ is an attached pronoun built on sukūn in the accusative position as its object.');

// Additional indeclinable and pronominal components caught by the contextual rerun.
setAuditedAnswerAt('raf-07',1,'إِذَا','ظَرْفُ زَمَانٍ لِلْمُسْتَقْبَلِ مُتَضَمِّنٌ مَعْنَى الشَّرْطِ، مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ.','A future-time adverb containing a conditional meaning, built on sukūn in the accusative position.');
setAuditedAnswerAt('nasb-19',1,'إِلَّا','أَدَاةُ اسْتِثْنَاءٍ مَبْنِيَّةٌ عَلَى السُّكُونِ، لَا مَحَلَّ لَهَا مِنَ الْإِعْرَابِ.','An exception particle built on sukūn, with no syntactic position.');
setAuditedAnswerAt('noun-10',3,'تُؤْمَرُونَ','فِعْلٌ مُضَارِعٌ مَبْنِيٌّ لِلْمَجْهُولِ مَرْفُوعٌ بِثُبُوتِ النُّونِ؛ لِأَنَّهُ مِنَ الْأَفْعَالِ الْخَمْسَةِ، وَوَاوُ الْجَمَاعَةِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ نَائِبُ فَاعِلٍ، وَالْجُمْلَةُ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.','Passive present verb, indicative with retained nūn because it is one of the five forms. Plural wāw is an attached pronoun built on sukūn in the nominative position as deputy subject; the clause is in the genitive position as the second term of the iḍāfah.');
setAuditedAnswerAt('raf-05',2,'تَرْضَوْنَهَا','فِعْلٌ مُضَارِعٌ مَرْفُوعٌ بِثُبُوتِ النُّونِ؛ لِأَنَّهُ مِنَ الْأَفْعَالِ الْخَمْسَةِ، وَوَاوُ الْجَمَاعَةِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ فَاعِلٌ، وَ«هَا» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ مَفْعُولٌ بِهِ، وَالْجُمْلَةُ فِي مَحَلِّ رَفْعٍ صِفَةٌ.','Present verb, indicative with retained nūn because it is one of the five forms. Plural wāw is an attached pronoun built on sukūn in the nominative position as subject; hā is an attached pronoun built on sukūn in the accusative position as object. The clause is in the nominative position as an adjective.');
setAuditedAnswerAt('raf-13',2,'أَبُوهُمْ','فَاعِلٌ مَرْفُوعٌ بِالْوَاوِ نِيَابَةً عَنِ الضَّمَّةِ؛ لِأَنَّهُ مِنَ الْأَسْمَاءِ السِّتَّةِ وَهُوَ مُضَافٌ، وَ«هُمْ» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.','Subject of the verb, nominative with wāw instead of ḍammah because it is one of the six nouns and is annexed. Hum is an attached pronoun built on sukūn in the genitive position as the second term of the iḍāfah.');
setAuditedAnswerAt('raf-21',3,'يَسْجُدَانِ','فِعْلٌ مُضَارِعٌ مَرْفُوعٌ بِثُبُوتِ النُّونِ؛ لِأَنَّهُ مِنَ الْأَفْعَالِ الْخَمْسَةِ، وَأَلِفُ الِاثْنَيْنِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ فَاعِلٌ، وَالْجُمْلَةُ فِي مَحَلِّ رَفْعٍ خَبَرٌ.','Present verb, indicative with retained nūn because it is one of the five forms. Dual alif is an attached pronoun built on sukūn in the nominative position as subject; the clause is in the nominative position as predicate.');
setAuditedAnswerAt('raf-22',2,'يُؤْمِنُونَ','فِعْلٌ مُضَارِعٌ مَرْفُوعٌ بِثُبُوتِ النُّونِ؛ لِأَنَّهُ مِنَ الْأَفْعَالِ الْخَمْسَةِ، وَوَاوُ الْجَمَاعَةِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.','Present verb, indicative with retained nūn because it is one of the five forms. Plural wāw is an attached pronoun built on sukūn in the nominative position as subject.');
setAuditedAnswerAt('raf-23',1,'أَتَعْجَبِينَ','الْهَمْزَةُ حَرْفُ اسْتِفْهَامٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«تَعْجَبِينَ» فِعْلٌ مُضَارِعٌ مَرْفُوعٌ بِثُبُوتِ النُّونِ؛ لِأَنَّهُ مِنَ الْأَفْعَالِ الْخَمْسَةِ، وَيَاءُ الْمُخَاطَبَةِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.','The interrogative hamzah is built on fatḥ and has no syntactic position. Taʿjabīna is a present verb, indicative with retained nūn because it is one of the five forms; feminine-address yāʾ is an attached pronoun built on sukūn in the nominative position as subject.');
setAuditedAnswerAt('nasb-07',4,'لُحُومُهَا','«لُحُومُ» فَاعِلٌ مُؤَخَّرٌ مَرْفُوعٌ بِالضَّمَّةِ الظَّاهِرَةِ، وَهُوَ مُضَافٌ، وَ«هَا» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.','Luḥūmu is the delayed subject, nominative with a visible ḍammah and the first term of an iḍāfah. Hā is an attached pronoun built on sukūn in the genitive position as the second term.');
setAuditedAnswerAt('nasb-07',6,'دِمَاؤُهَا','«دِمَاءُ» مَعْطُوفٌ عَلَى «لُحُومُهَا» مَرْفُوعٌ بِالضَّمَّةِ الظَّاهِرَةِ، وَهُوَ مُضَافٌ، وَ«هَا» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.','Dimāʾu is coordinated with luḥūmuhā, nominative with a visible ḍammah and the first term of an iḍāfah. Hā is an attached pronoun built on sukūn in the genitive position as the second term.');
setAuditedAnswerAt('nasb-08',7,'رِجَالِكُمْ','«رِجَالِ» اسْمٌ مَجْرُورٌ بِـ«مِنْ»، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ، وَ«كُمْ» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ، وَشِبْهُ الْجُمْلَةِ صِفَةٌ لِـ«أَحَدٍ».','Rijāli is governed by min, genitive with a visible kasrah and the first term of an iḍāfah. Kum is an attached pronoun built on sukūn in the genitive position as the second term; the phrase describes aḥadin.');
setAuditedAnswerAt('nasb-19',3,'تَكُونَا','فِعْلٌ مُضَارِعٌ نَاسِخٌ مَنْصُوبٌ بِـ«أَنْ»، وَعَلَامَةُ نَصْبِهِ حَذْفُ النُّونِ؛ لِأَنَّهُ مِنَ الْأَفْعَالِ الْخَمْسَةِ، وَأَلِفُ الِاثْنَيْنِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ اسْمُهُ.','A defective present verb made subjunctive by an, marked by deletion of nūn because it is one of the five forms. Dual alif is an attached pronoun built on sukūn in the nominative position as its noun.');
setAuditedAnswerAt('nasb-20',2,'تَصُومُوا','فِعْلٌ مُضَارِعٌ مَنْصُوبٌ بِـ«أَنْ»، وَعَلَامَةُ نَصْبِهِ حَذْفُ النُّونِ؛ لِأَنَّهُ مِنَ الْأَفْعَالِ الْخَمْسَةِ، وَوَاوُ الْجَمَاعَةِ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.','A present verb made subjunctive by an, marked by deletion of nūn because it is one of the five forms. Plural wāw is an attached pronoun built on sukūn in the nominative position as subject.');
setAuditedAnswerAt('nasb-10',2,'حَمَاكَ','«حَمَا» مَفْعُولٌ بِهِ، وَعَلَامَةُ نَصْبِهِ الْأَلِفُ نِيَابَةً عَنِ الْفَتْحَةِ؛ لِأَنَّهُ مِنَ الْأَسْمَاءِ السِّتَّةِ وَهُوَ مُضَافٌ، وَالْكَافُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.','Ḥamā is the direct object, accusative with alif instead of fatḥah because it is one of the six nouns, and the first term of an iḍāfah. Kāf is an attached pronoun built on fatḥ in the genitive position as the second term.');
setAuditedAnswerAt('nasb-10',3,'وَهَنَاكَ','الْوَاوُ حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«هَنَا» مَعْطُوفٌ عَلَى «حَمَاكَ»، وَعَلَامَةُ نَصْبِهِ الْأَلِفُ نِيَابَةً عَنِ الْفَتْحَةِ؛ لِأَنَّهُ مِنَ الْأَسْمَاءِ السِّتَّةِ وَهُوَ مُضَافٌ، وَالْكَافُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.','The wāw coordinates and is built on fatḥ with no syntactic position. Hanā is coordinated with ḥamāka, accusative with alif instead of fatḥah because it is one of the six nouns, and the first term of an iḍāfah. Kāf is an attached pronoun built on fatḥ in the genitive position as the second term.');
setAuditedAnswerAt('nasb-16',1,'رَبَّنَا','مُنَادًى مُضَافٌ حُذِفَ مِنْهُ حَرْفُ النِّدَاءِ، مَنْصُوبٌ بِالْفَتْحَةِ الظَّاهِرَةِ، وَهُوَ مُضَافٌ، وَ«نَا» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.','A vocative noun in an iḍāfah with the vocative particle omitted, accusative with a visible fatḥah and the first term of the iḍāfah. Nā is an attached pronoun built on sukūn in the genitive position as the second term.');

